    all_content = []
    for filepath in sorted(files):
        with open(filepath, 'r') as f:
            content = f.read()
        all_content.append({'filename': filepath.split('/')[-1], 'content': content})
    return pd.DataFrame(all_content)

def load() -> pd.DataFrame:
    import re

    with open('data/astronomy/input/geomag_forecast/0309geomag_forecast.txt', 'r') as f:
        content = f.read()

    # Extract the "Predicted Ap" line for Mar 10-12
    # Format: "Predicted Ap 10 Mar-12 Mar 025-020-012"
    match = re.search(r'Predicted Ap.*?(\d+)-(\d+)-(\d+)', content)
    if match:
        mar10_pred = float(match.group(1))
        mar11_pred = float(match.group(2))
        mar12_pred = float(match.group(3))

        return pd.DataFrame({
            'date': ['2025-03-10', '2025-03-11', '2025-03-12'],
            'predicted_ap': [mar10_pred, mar11_pred, mar12_pred]
        })

    return pd.DataFrame()

def load() -> pd.DataFrame:
    import glob
    files = sorted(glob.glob('data/astronomy/input/geomag_forecast/*geomag_forecast.txt'))
    results = []

    for fpath in files:
        with open(fpath, 'r') as f:
            content = f.read()

        lines = content.split('\n')
        for i, line in enumerate(lines):
            if 'Observed Ap' in line:
                parts = line.split()
                if len(parts) >= 4:
                    date_str = parts[2] + ' ' + parts[3]
                    ap_val = int(parts[4]) if len(parts) > 4 else None
                    if ap_val is not None:
                        results.append({
                            'date_label': date_str,
                            'ap_value': ap_val,
                            'source_file': fpath.split('/')[-1]
                        })

    return pd.DataFrame(results)
